int first = countMatches(data, 5, rule); // 3

bool isNegative(long x) { return x < 0; }
// Back in the calling function:
rule = isNegative;
int second = countMatches(data, 5, rule); // 1

parts:
struct Money {
    int cents;
    // Write the member operators here.
};

answers:
struct Money {
    int cents;
    Money operator+(const Money& rhs) const {
        return Money{cents + rhs.cents};
    }
    Money& operator+=(const Money& rhs) {
        cents += rhs.cents;
        return *this;
    }
};

